import React, { useMemo, useState } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Collapse,
  Stack,
  Typography,
} from '@mui/material';
import { alpha, useTheme } from '@mui/material/styles';
import { Link as RouterLink } from 'react-router-dom';
import {
  Cell,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
} from 'recharts';
import { GHG_SCOPE_HEX, formatCo2eFromKg } from '../../constants/carbonVisualization';
import PlainLanguageLabel from './PlainLanguageLabel';
import { contentBoxSx } from '../../constants/appShellLayout';

export type FootprintStorySource = {
  name: string;
  kg: number;
};

export type FootprintStoryPanelProps = {
  totalKg: number;
  scope1Kg: number;
  scope2Kg: number;
  scope3Kg: number;
  topSources?: FootprintStorySource[];
  primaryCta?: { label: string; path: string };
  secondaryCta?: { label: string; path: string };
  details?: React.ReactNode;
  title?: string;
  /** Supporting line under the big number */
  summary?: string;
  emptySummary?: string;
};

const FootprintStoryPanel: React.FC<FootprintStoryPanelProps> = ({
  totalKg,
  scope1Kg,
  scope2Kg,
  scope3Kg,
  topSources = [],
  primaryCta,
  secondaryCta,
  details,
  title = 'Your footprint story',
  summary,
  emptySummary,
}) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const [showDetails, setShowDetails] = useState(false);

  const pieData = useMemo(() => (
    [
      { name: 'Direct (fuel & onsite)', key: 'scope1', kg: Math.max(0, scope1Kg), fill: GHG_SCOPE_HEX.scope1 },
      { name: 'Electricity', key: 'scope2', kg: Math.max(0, scope2Kg), fill: GHG_SCOPE_HEX.scope2 },
      { name: 'Suppliers & travel', key: 'scope3', kg: Math.max(0, scope3Kg), fill: GHG_SCOPE_HEX.scope3 },
    ].filter((row) => row.kg > 0)
  ), [scope1Kg, scope2Kg, scope3Kg]);

  const sources = useMemo(
    () => [...topSources].filter((s) => s.kg > 0).sort((a, b) => b.kg - a.kg).slice(0, 3),
    [topSources]
  );

  const total = Math.max(0, totalKg);
  const hasData = total > 0 || pieData.length > 0;
  const scopeLegend = [
    { termId: 'scope_1', name: 'Direct', kg: Math.max(0, scope1Kg), fill: GHG_SCOPE_HEX.scope1 },
    { termId: 'scope_2', name: 'Electricity', kg: Math.max(0, scope2Kg), fill: GHG_SCOPE_HEX.scope2 },
    { termId: 'scope_3', name: 'Value chain', kg: Math.max(0, scope3Kg), fill: GHG_SCOPE_HEX.scope3 },
  ];

  return (
    <Card
      sx={{
        mb: 3,
        border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.3 : 0.16)}`,
        background: isDark
          ? `linear-gradient(145deg, ${theme.palette.background.paper} 0%, ${alpha(theme.palette.primary.dark, 0.1)} 100%)`
          : 'linear-gradient(135deg, #ffffff 0%, #ecfdf5 50%, #f8fafc 100%)',
      }}
    >
      <CardContent sx={{ p: { xs: 2, md: 3 } }}>
        <Typography variant="overline" color="text.secondary" sx={{ fontWeight: 700, letterSpacing: '0.08em' }}>
          {title}
        </Typography>
        <Stack
          direction={{ xs: 'column', lg: 'row' }}
          spacing={3}
          alignItems={{ xs: 'stretch', lg: 'center' }}
          sx={{ mt: 1 }}
        >
          <Box sx={{ flex: 1.1, ...contentBoxSx }}>
            <Typography variant="h3" sx={{ fontWeight: 800, letterSpacing: '-0.03em', lineHeight: 1.1 }}>
              {hasData ? formatCo2eFromKg(total) : '—'}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 0.75, maxWidth: 420 }}>
              {hasData
                ? (summary
                  || 'Simple view of where your emissions come from. Upload bills or map operations to refine this picture.')
                : (emptySummary
                  || 'Upload electricity or fuel bills to see your first footprint picture.')}
            </Typography>

            {sources.length > 0 ? (
              <Stack spacing={0.75} sx={{ mt: 2 }}>
                <Typography variant="caption" sx={{ fontWeight: 700 }} color="text.secondary">
                  Top sources
                </Typography>
                {sources.map((source, index) => (
                  <Stack key={source.name} direction="row" justifyContent="space-between" spacing={2}>
                    <Typography variant="body2">
                      {index + 1}. {source.name}
                    </Typography>
                    <Typography variant="body2" sx={{ fontWeight: 700 }}>
                      {formatCo2eFromKg(source.kg)}
                    </Typography>
                  </Stack>
                ))}
              </Stack>
            ) : null}

            <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" sx={{ mt: 2.5 }}>
              {primaryCta ? (
                <Button component={RouterLink} to={primaryCta.path} variant="contained">
                  {primaryCta.label}
                </Button>
              ) : null}
              {secondaryCta ? (
                <Button component={RouterLink} to={secondaryCta.path} variant="outlined">
                  {secondaryCta.label}
                </Button>
              ) : null}
              {details ? (
                <Button size="small" onClick={() => setShowDetails((v) => !v)}>
                  {showDetails ? 'Hide details' : 'See detailed charts'}
                </Button>
              ) : null}
            </Stack>
          </Box>

          <Box sx={{ width: { xs: '100%', lg: 280 }, ...contentBoxSx }}>
            {pieData.length > 0 ? (
              <Box sx={{ width: '100%', minWidth: 0, maxWidth: '100%', height: 200 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={pieData}
                      dataKey="kg"
                      nameKey="name"
                      innerRadius={52}
                      outerRadius={80}
                      paddingAngle={2}
                    >
                      {pieData.map((entry) => (
                        <Cell key={entry.key} fill={entry.fill} />
                      ))}
                    </Pie>
                    <Tooltip
                      formatter={(value: number) => formatCo2eFromKg(Number(value) || 0)}
                    />
                  </PieChart>
                </ResponsiveContainer>
              </Box>
            ) : (
              <Box
                sx={{
                  height: 200,
                  borderRadius: 2,
                  border: '1px dashed',
                  borderColor: 'divider',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  px: 2,
                }}
              >
                <Typography variant="body2" color="text.secondary" textAlign="center">
                  Chart appears after your first assessment
                </Typography>
              </Box>
            )}
            {hasData && (
              <Stack
                component="ul"
                spacing={0.5}
                aria-label="Scope legend"
                sx={{ listStyle: 'none', m: 0, mt: 1, p: 0 }}
              >
                {scopeLegend.map((item) => (
                  <Stack
                    key={item.termId}
                    component="li"
                    direction="row"
                    spacing={1}
                    alignItems="center"
                    justifyContent="space-between"
                  >
                    <Stack direction="row" spacing={0.75} alignItems="center" sx={{ minWidth: 0 }}>
                      <Box
                        aria-hidden
                        sx={{ width: 10, height: 10, borderRadius: '50%', bgcolor: item.fill, flexShrink: 0 }}
                      />
                      <Typography variant="caption" color="text.secondary" noWrap>
                        <PlainLanguageLabel termId={item.termId}>{item.name}</PlainLanguageLabel>
                      </Typography>
                    </Stack>
                    <Typography variant="caption" sx={{ fontWeight: 700, whiteSpace: 'nowrap' }}>
                      {formatCo2eFromKg(item.kg)}
                    </Typography>
                  </Stack>
                ))}
              </Stack>
            )}
          </Box>
        </Stack>

        {details ? (
          <Collapse in={showDetails}>
            <Box sx={{ mt: 3 }}>{details}</Box>
          </Collapse>
        ) : null}
      </CardContent>
    </Card>
  );
};

export default FootprintStoryPanel;
