/**
 * In-page graph panels for the lengthy Carbon Analytics workspace tab.
 * Selected via `?graph=` under `?section=carbon-analytics`.
 */
export const CARBON_ANALYTICS_GRAPH_PANELS = [
  {
    id: 'disclosure',
    label: 'Disclosure reporting graphs',
    description: 'Reporting graphs for this inventory. Scope totals stay on Overview.',
  },
  {
    id: 'intensity',
    label: 'Intensity',
    description: 'Emissions per employee, per activity row, and per rupee. The forward projection is on Forecasting.',
  },
] as const;

/** Older analytics graph ids now belong on another Carbon footprint page. */
export const RETIRED_CARBON_ANALYTICS_GRAPH_REDIRECTS: Record<string, string> = {
  assessment: '/carbon-footprint?section=overview',
  'by-source': '/carbon-footprint?section=overview',
  deepdive: '/carbon-footprint?section=overview',
  recommendations: '/carbon-footprint?section=recommendations',
};

export type CarbonAnalyticsGraphPanelId = (typeof CARBON_ANALYTICS_GRAPH_PANELS)[number]['id'];

export const DEFAULT_CARBON_ANALYTICS_GRAPH_PANEL: CarbonAnalyticsGraphPanelId = 'disclosure';

export function resolveCarbonAnalyticsGraphPanel(
  search: string | null | undefined
): CarbonAnalyticsGraphPanelId {
  const raw = new URLSearchParams(search || '').get('graph')?.trim().toLowerCase() || '';
  const match = CARBON_ANALYTICS_GRAPH_PANELS.find((panel) => panel.id === raw);
  return match?.id ?? DEFAULT_CARBON_ANALYTICS_GRAPH_PANEL;
}

export function carbonAnalyticsGraphHref(panelId: CarbonAnalyticsGraphPanelId): string {
  return `/carbon-footprint?section=carbon-analytics&graph=${panelId}`;
}
