import React, { useCallback } from 'react';
import { Box, Button, Chip, Stack, Tooltip, Typography } from '@mui/material';
import {
  CheckCircle as CheckCircleIcon,
  CheckBoxOutlineBlank as UncheckedIcon,
} from '@mui/icons-material';
import type { MitigationAction, SelectedMitigationAction } from '../../types/mitigation';

export interface MitigationActionPickerProps {
  actions: MitigationAction[];
  selectedActions?: SelectedMitigationAction[];
  disabled?: boolean;
  savingActionId?: string | null;
  onToggleAction: (action: MitigationAction, selected: boolean) => void;
}

const isActionSelected = (
  actionId: string,
  selectedActions: SelectedMitigationAction[] = []
): boolean => selectedActions.some((item) => item.actionId === actionId);

const MitigationActionPicker: React.FC<MitigationActionPickerProps> = ({
  actions,
  selectedActions = [],
  disabled = false,
  savingActionId = null,
  onToggleAction,
}) => {
  const handleToggle = useCallback(
    (action: MitigationAction) => {
      const currentlySelected = isActionSelected(action.id, selectedActions);
      onToggleAction(action, !currentlySelected);
    },
    [onToggleAction, selectedActions]
  );

  if (!actions.length) {
    return (
      <Typography variant="caption" color="text.secondary">
        No specific measures available for this recommendation yet.
      </Typography>
    );
  }

  const selectedCount = selectedActions.length;
  const estimatedTotal = selectedActions.reduce(
    (sum, item) => sum + (Number(item.estimatedImpactKg) || 0),
    0
  );

  return (
    <Box sx={{ mt: 1.5 }}>
      <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 1 }} flexWrap="wrap">
        <Typography variant="caption" color="text.secondary" fontWeight={600}>
          Choose mitigation measures
        </Typography>
        {selectedCount > 0 && (
          <Chip
            size="small"
            color="primary"
            variant="outlined"
            label={`${selectedCount} selected · ~${estimatedTotal.toFixed(1)} kg CO₂e`}
          />
        )}
      </Stack>
      <Stack direction="row" flexWrap="wrap" gap={0.75}>
        {actions.map((action) => {
          const selected = isActionSelected(action.id, selectedActions);
          const isSaving = savingActionId === action.id;
          const tooltip = [
            action.description,
            action.estimatedImpactKg != null && action.estimatedImpactKg > 0
              ? `Estimated impact: ~${action.estimatedImpactKg} kg CO₂e`
              : null,
            action.implementationTrack
              ? `Track: ${action.implementationTrack.replace(/_/g, ' ')}`
              : null,
          ]
            .filter(Boolean)
            .join(' · ');

          return (
            <Tooltip key={action.id} title={tooltip || action.label} arrow>
              <span>
                <Button
                  size="small"
                  variant={selected ? 'contained' : 'outlined'}
                  color={selected ? 'success' : 'inherit'}
                  disabled={disabled || isSaving}
                  onClick={() => handleToggle(action)}
                  startIcon={
                    selected ? (
                      <CheckCircleIcon fontSize="small" />
                    ) : (
                      <UncheckedIcon fontSize="small" />
                    )
                  }
                  sx={{
                    textTransform: 'none',
                    borderRadius: 2,
                    maxWidth: { xs: '100%', sm: 320 },
                    justifyContent: 'flex-start',
                  }}
                >
                  {isSaving ? 'Saving…' : action.label}
                  {action.estimatedImpactKg != null && action.estimatedImpactKg > 0 && !isSaving ? (
                    <Typography
                      component="span"
                      variant="caption"
                      sx={{ ml: 0.75, opacity: 0.85 }}
                    >
                      (~{action.estimatedImpactKg} kg)
                    </Typography>
                  ) : null}
                </Button>
              </span>
            </Tooltip>
          );
        })}
      </Stack>
    </Box>
  );
};

export default MitigationActionPicker;
